public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(this.Hours < 0)
        ret = checkFailed(strFmt("%1 must be greater than or equal to 0", fieldPName(NVHcmWorkerFlightHours, Hours)));

    if(this.FromDate > this.ToDate)
        ret = checkFailed(strFmt("%1 must be greater or equal to %2.", fieldPName(NVHcmWorkerFlightHours, FromDate), fieldPName(NVHcmWorkerFlightHours, ToDate)));

    ret = this.validateDateOverlap();

    return ret;
}

private boolean validateDateOverlap()
{
    NVHcmWorkerFlightHours otherFlightHours;

    while select otherFlightHours
        where otherFlightHours.RecId    != this.RecId
            && otherFlightHours.Worker  == this.Worker
            && (this.FromDate           <= otherFlightHours.ToDate && this.ToDate >= otherFlightHours.FromDate)
    {            
        return checkFailed("Dates are overlapping with other record. Period must be unique to proceed.");
    }

    return true;
}

[SysClientCacheDataMethodAttribute(true)]
public display Days totalDays()
{
    return this.ToDate - this.FromDate + 1;
}

[SysClientCacheDataMethodAttribute(true)]
public display Hours totalHours()
{
    NVHcmWorkerFlightHours flightHours;

    select sum(Hours) from flightHours
        where flightHours.Worker    == this.Worker
            && flightHours.ToDate   < this.FromDate;

    return flightHours.Hours + this.Hours;
}

[SysClientCacheDataMethodAttribute(true)]
public display Hours totalHoursCurrentYear()
{
    NVHcmWorkerFlightHours flightHours;
    FromDate currentYearStartDate = mkDate(1, 1, Year(this.FromDate));

    select sum(Hours) from flightHours
        where flightHours.Worker        == this.Worker
            && flightHours.ToDate       < this.FromDate
            && flightHours.FromDate     >= currentYearStartDate;

    return flightHours.Hours  + this.Hours;
}

public static Hours totalHoursYear(HcmWorkerRecId _worker, date _yearDate = today())
{
    NVHcmWorkerFlightHours flightHours;
    FromDate currentYearStartDate = mkDate(1, 1, Year(_yearDate));

    select sum(Hours) from flightHours
        where flightHours.Worker        == _worker
            && flightHours.FromDate     >= currentYearStartDate;

    return flightHours.Hours;
}
